"""Build a standalone report exclusively from the anonymized public evidence."""
from pathlib import Path
import html,json
ROOT=Path(__file__).resolve().parents[1]
load=lambda name:json.loads((ROOT/'evidence'/name).read_text(encoding='utf8'))
data=load('results.json');cases=data['cases'];rounds=data['rounds'];timelines=load('kv-timelines.json')
esc=lambda x:html.escape(str(x))
def fmt(x):return f'{x:,.3f}' if isinstance(x,float) else str(x)
def table(rows,cols):
    return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+esc(title)+'</th>' for key,title in cols)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+esc(fmt(r.get(key,'')))+'</td>' for key,title in cols)+'</tr>' for r in rows)+'</tbody></table></div>'
labels={'c4':'C4 / KV 6.25 GiB 基线','c3':'C3','budget90':'Token 准入 90%','budget95':'Token 准入 95%','kv6p5':'C4 / KV 6.5 GiB','kv6p75':'C4 / KV 6.75 GiB','chunk2048':'C4 / KV 6.5 GiB / chunk2048'}
for c in cases:c['label']=labels[c['case']]
best=next(c for c in cases if c['case']==data['default']);maximum=max(c['effective_items_per_minute'] for c in cases)
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Qwen3-Omni · 多 FULL Graph 与 KV 优化</title><style>
body{margin:0;background:#f6f7fa;color:#242936;font:14px/1.8 "Segoe UI","Microsoft YaHei",sans-serif}header{border-top:6px solid #c7000b;background:#fff;padding:28px max(24px,calc((100vw - 1400px)/2))}main{max-width:1400px;margin:auto;padding:22px}section{padding:24px;border:1px solid #e1e5ec;border-radius:10px;background:#fff;margin-bottom:20px}h2{margin-top:0;font-size:21px}.note{background:#fff2f2;border-left:4px solid #c7000b;padding:14px}.scroll{overflow:auto}table{border-collapse:collapse;min-width:850px;width:100%;font-size:12px}th,td{padding:9px;border-bottom:1px solid #e4e7ed;text-align:left}th{background:#f3f5f8}.bar{display:grid;grid-template-columns:260px 1fr 100px;gap:12px;align-items:center;margin:12px 0}.track{background:#f6e8e8}.fill{height:26px;background:#c7000b}svg{width:100%;height:auto}pre{white-space:pre-wrap;background:#f5f6f9;padding:14px}small{color:#606b7b}@media(max-width:650px){.bar{grid-template-columns:170px 1fr 85px}section{padding:15px}}</style>
<header><small>2026-10-21 · RTX 5090 32 GiB · TP1 · 原生 vLLM · Thinking</small><h1>多 FULL Graph ＋ KV 容量优化</h1></header><main>'''
page+=f'<section><h2>结果与采用配置</h2><p class="note"><b>{best["effective_items_per_minute"]:.3f} 有效条/分钟，较本轮 C4 基线 +{best["effective_change_pct"]:.2f}%</b>。保留 C4、多 FULL Graph、FP8 KV 6.5 GiB、chunk4096；三轮45/45有效、零抢占。</p><p>输出 TPS/卡为完整轮的轮间中位数 <b>{best["median_tps"]:.2f}</b>；主吞吐为所有正式尝试的有效条数除以总 wall。22轮共330条，329条通过完整性校验：原C4首轮一条返回sample_id不匹配，正常停止、未截断；其耗时保留。全部包含Thinking。采用规则为较基线至少2%才换默认，否则保留简单基线；不是显著性检验。</p><p>KV峰值99.10%，当前零抢占不保证更长输入或Thinking输出仍不抢占。<b>完整性和数值检查不等同Caption语义精度。</b></p></section>'
page+='<section><h2>七组配置与有效吞吐</h2>'+table(cases,[('label','方案'),('kv_gib','KV/GiB'),('chunk','chunk'),('concurrency','客户端上限'),('ratio','token准入比例'),('attempts','轮数'),('qualified_rounds','完整轮'),('valid_captions','有效'),('requests','总请求'),('effective_items_per_minute','有效条/min'),('effective_change_pct','较基线/%'),('preemptions','抢占'),('kv_peak_pct','KV峰值/%')])
for c in cases:
    page+=f'<div class="bar"><span>{esc(c["label"])}</span><div class="track"><div class="fill" style="width:{c["effective_items_per_minute"]/maximum*100:.3f}%"></div></div><b>{c["effective_items_per_minute"]:.3f} 条/min</b></div>'
page+='<p>C3和比例准入消除了观察到的抢占，但让有效吞吐下降。6.5GiB保持C4并减少重算，本轮表现最佳；继续扩大到6.75GiB没有进一步收益。chunk2048叠加在6.5GiB方案上，比该父方案约低7.26%，共2次抢占。表内提升统一相对本轮C4基线，不能误读为相对父方案。</p></section>'
page+='<section><h2>完整轮的速度中位数</h2>'+table(cases,[('label','方案'),('median_tps','输出 TPS/卡'),('median_output_tokens_per_caption','每条输出tokens均值的轮间中位数'),('median_ttft_seconds','TTFT P50/s'),('median_tpot_ms','TPOT P50/ms'),('median_sample_e2e_seconds','处理 E2E P50/s')])+'<p>各项先在轮内计算，再取完整轮的中位数。自然输出长度变化会影响条/分钟，不能把全部提升归为硬件速度。TPS包括Thinking与正文；TP1直接折算为每卡吞吐。预热、编译和显存诊断不进入正式排名。</p></section>'
page+='<section><h2>逐轮结果与无效项</h2>'+table(rounds,[('name','轮次'),('qualified','完整合格'),('valid','有效/15'),('truncated','截断'),('other_invalid','非截断无效'),('id_mismatches','ID不匹配'),('tokens','输出tokens'),('wall','wall/s'),('items','有效条/min'),('tps','TPS/卡'),('ttft','TTFT P50/s'),('tpot','TPOT P50/ms'),('e2e','处理E2E P50/s'),('queue_p50','客户端排队P50/s'),('dataset_e2e_p50','提交到结束P50/s'),('preemptions','抢占')])+'<p>未修改模型返回的ID以修正无效项。原C4有四次正式尝试，其中三次完整；其余各方案三轮均完整，所有尝试均进入主吞吐分母。</p></section>'
page+='<section><h2>输入与计时合同</h2><p>15条冻结视频，每条一个原视频及同步音轨、全部参考图（合计64张，部分样本4–5张）、长system prompt及冻结ShotPlan/runtime context。视频2fps；每轮419,460输入tokens。视频总长'+f'{data["protocol"]["unique_video_seconds"]:.2f}s，单条{data["protocol"]["min_video_seconds"]:.2f}–{data["protocol"]["max_video_seconds"]:.2f}s。温度0、seed0、enable_thinking=true、输出上限24,576、上下文65,536。</p><p>初始自然单条预热；服务重配后4条×4096固定输出仅用于预热和Graph校验，ignore_eos导致的长度停止不算自然Caption质量。另一次15条显存诊断也不排名。初始C3/C4、90%/95%准入交错执行；容量及chunk按顺序执行，未做随机交错。</p><p><b>TTFT</b>：推理HTTP发出到首个Thinking或正文片段。<b>TPOT</b>=(请求E2E−TTFT)/(completion tokens−1)，是平均token耗时，不是相邻SSE间隔。<b>处理E2E</b>包括客户端媒体准备和推理，但不含客户端排队；token预检时间单独排除。<b>提交到结束E2E</b>包含线程池/token准入等待。批次wall包含全部正式客户端排队及输出。</p><p>主有效条/分钟=sum(校验有效Caption)/sum(全部正式尝试wall)×60。公开匿名逐条指标与输入语义哈希可审核配对；媒体、prompt与输出内容不公开。15条性能集没有人工真值，不能据此声称音频分类、H800对比精度或Caption质量无损。</p></section>'
page+='<section><h2>保留的计算与 Graph 路径</h2><p>非官方Thinking-heretic-NVFP4 checkpoint；96个attention QKV/O线性层FP8 E4M3 W8A8，48层MoE保留NVFP4，48层KV为FP8 E4M3并使用固定scales。原生vLLM V1、异步调度、N3/K3 GPU n-gram、XQA BF16 Q。GPU n-gram查询已有token，不含小模型权重或独立的FP8精度设置。</p><p>FULL_AND_PIECEWISE和原有capture sizes=[1,2,4,8,16]保留。最多4请求、query∈{1,4}的30个有序形状中，4个全4形状保留原FULL，额外捕获26张FULL；按精确query元组分派并缓存ragged mask。仅升级真正decode，prefill/encoder/其他query、强制eager、cascade继续走原回退路径。不是全流程强制FULL，也不是仅改变Graph的纯消融。prepare融合补丁未启用。</p>'+table(data['graph_checks'],[('phase','审计阶段'),('checks','比较数'),('shapes','遇到形状数'),('all_exact','逐元素一致')])+'<p>最终运行检查45次前向逐元素一致，覆盖24种遇到的额外形状；启动捕获26张与实际校验覆盖数分别记录。所有正式轮检查请求计数、GPU归属、输入哈希和token数；4个关键安装源码哈希开始/结束一致。</p></section>'
page+='<section><h2>显存核算与 KV 扩容</h2>'+table(data['memory_table'],[('stage','阶段'),('allocated','Torch活跃/GiB'),('reserved','Torch保留/GiB'),('free','CUDA空闲/GiB'),('peak_allocated','活跃峰值/GiB'),('non_torch','非Torch/GiB')])+'<pre>'+esc(json.dumps(data['memory_decision'],ensure_ascii=False,indent=2))+'</pre><p>独立MemoryAuditWorker记录allocator、非Torch分配及Graph池；在确认请求空闲后empty_cache并重置峰值，Graph池保留。安全公式扣除活跃峰值、非Torch峰值、Graph池不可回收闲置及512MiB余量。观测允许再分配约616MiB，因此6.5/6.75GiB均获准尝试，再分别通过启动/预热/三轮自然请求。不是任意负载的OOM保证。</p><p>最长四条prompt合计136,188tokens，6.25GiB KV容量136,528tokens，仅差340tokens且尚未计生成；实际是分阶段调度，不能由加和单独断言必然抢占。6.5/6.75GiB容量分别141,984/147,456tokens。</p></section>'
page+='<section><h2>KV 时间线：各方案第一轮完整结果</h2><p>1Hz遥测；红线为KV使用率，红点为抢占累计数增长。横轴为该轮相对秒数，不是逐毫秒GPU profiling。</p>'
for c in cases:
    run=next(r['name'] for r in rounds if r['case']==c['case'] and r['qualified']);samples=timelines[run]
    span=max(1,samples[-1]['seconds']);points=[];dots=[];previous=0
    for row in samples:
        x=60+row['seconds']/span*1020;y=180-row['kv_usage']*140;points.append(f'{x:.2f},{y:.2f}')
        if row['preemptions']>previous:dots.append(f'<circle cx="{x:.2f}" cy="{y:.2f}" r="4" fill="#c7000b"/>')
        previous=row['preemptions']
    page+='<h3>'+esc(c['label'])+' · '+esc(run)+'</h3><svg viewBox="0 0 1120 220" role="img" aria-label="KV使用率时间线"><rect width="1120" height="220" fill="#fafbfc"/>'
    for percent in [0,50,100]:
        y=180-percent/100*140;page+=f'<line x1="60" y1="{y}" x2="1080" y2="{y}" stroke="#dce2ea"/><text x="10" y="{y+5}">{percent}%</text>'
    page+='<polyline points="'+' '.join(points)+'" fill="none" stroke="#c7000b" stroke-width="1.6"/>'+''.join(dots)+f'<text x="60" y="208">0 s</text><text x="990" y="208">{span:.1f} s</text></svg>'
page+='</section><section><h2>复现范围与发布说明</h2><p>Python3.10、vLLM0.30.0、PyTorch2.13.0+CUDA13.0、FlashInfer0.6.18.post1、GCC11工具链。精确版本和关键源码指纹随目录提供；原环境有兼容修改，不能保证pip安装同版本即可一致。Worker及请求客户端按实测源码保留，新的路径/进程包装脚本在本次发布中未重新跑GPU。</p><p>新增目录提供configs/runtime/benchmark/scripts/environment/data/evidence/report，历史方案和原报告保留。对比旧N3报告时注意旧输出上限为16384，本轮为24576，不能直接归因Graph或KV收益。公开包按白名单生成，不含登录资料、主机IP、私有路径、原数据来源、原始媒体、业务prompt、Caption或Thinking正文。</p></section></main></html>'
(ROOT/'report/report.html').write_text(page,encoding='utf8',newline='\n')
print('Standalone public report generated')
